import Link from "next/link";
import { useId } from "react";
import geometry from "@/lib/brand-geometry.json";
import { BRAND } from "@/lib/brand";
import { cn } from "@/lib/utils";

// =============================================================================
// QORVYNA brand identity — emblem + wordmark, drawn as inline vector shapes.
//
// The shapes come from src/lib/brand-geometry.json (generated by
// scripts/generate-brand-assets.mjs from the same source as every logo file and
// app icon), so the product chrome, the favicon and the exported logos are one
// drawing. Nothing is fetched from a third-party host, nothing flashes in late,
// and the wordmark's letters take the surrounding text colour so the identity
// reads correctly on light and dark surfaces without separate images.
// =============================================================================

const { emblem, emblemSmall, wordmark, palette } = geometry;

/** React ids can contain characters that are not valid inside `url(#…)`. */
function useSvgId(prefix: string): string {
  return `${prefix}${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
}

/**
 * The QORVYNA emblem: a "Q" crossed by an orbit, with a body riding it.
 * `compact` draws the heavier, orbit-free cut for very small sizes (≤ 24 px),
 * where an orbit thinner than a pixel would only blur.
 */
export function QorvynaMark({ className, compact = false, title }: { className?: string; compact?: boolean; title?: string }) {
  const id = useSvgId("qm");
  const label = title ? { role: "img" as const, "aria-label": title } : { "aria-hidden": true as const };

  if (compact) {
    return (
      <svg viewBox="0 0 512 512" className={cn("brand-mark", className)} focusable="false" {...label}>
        <defs>
          <linearGradient id={`${id}r`} gradientUnits="userSpaceOnUse" x1="330" y1="92" x2="110" y2="470">
            <stop offset="0" stopColor={palette.cyan} />
            <stop offset=".46" stopColor={palette.blue} />
            <stop offset="1" stopColor={palette.violet} />
          </linearGradient>
          <linearGradient id={`${id}t`} gradientUnits="userSpaceOnUse" x1="200" y1="282" x2="470" y2="470">
            <stop offset="0" stopColor={palette.cyan} />
            <stop offset="1" stopColor={palette.blueDeep} />
          </linearGradient>
          <mask id={`${id}c`} maskUnits="userSpaceOnUse" x="0" y="0" width="512" height="512">
            <rect width="512" height="512" fill="#fff" />
            <path d={emblemSmall.tailPath} fill="#000" stroke="#000" strokeWidth="34" strokeLinejoin="miter" />
          </mask>
        </defs>
        <path d={emblemSmall.ringPath} fillRule="evenodd" fill={`url(#${id}r)`} mask={`url(#${id}c)`} />
        <path d={emblemSmall.tailPath} fill={`url(#${id}t)`} />
        <circle cx={emblemSmall.body.cx} cy={emblemSmall.body.cy} r={emblemSmall.body.r} fill={palette.cyan} />
      </svg>
    );
  }

  const orbit = (
    <path d={emblem.orbitPath} fillRule="evenodd" fill={`url(#${id}o)`} />
  );
  const orbitCut = (
    <g transform={emblem.orbitTransform} clipPath={`url(#${id}nw)`}>
      <path d={emblem.orbitPath} fillRule="evenodd" fill="#000" stroke="#000" strokeWidth="12" />
    </g>
  );

  return (
    // The drawing sits in a 512 box with air around it; this viewBox trims that
    // air so the mark fills the square it is given.
    <svg viewBox="16 30 468 468" className={cn("brand-mark", className)} focusable="false" {...label}>
      <defs>
        <linearGradient id={`${id}r`} gradientUnits="userSpaceOnUse" x1="318" y1="108" x2="150" y2="420">
          <stop offset="0" stopColor={palette.cyan} />
          <stop offset=".46" stopColor={palette.blue} />
          <stop offset="1" stopColor={palette.violet} />
        </linearGradient>
        <linearGradient id={`${id}t`} gradientUnits="userSpaceOnUse" x1="222" y1="262" x2="430" y2="398">
          <stop offset="0" stopColor={palette.cyan} />
          <stop offset=".55" stopColor={palette.blue} />
          <stop offset="1" stopColor={palette.blueDeep} />
        </linearGradient>
        <linearGradient id={`${id}o`} gradientUnits="userSpaceOnUse" x1={-emblem.orbitRx} y1="0" x2={emblem.orbitRx} y2="0">
          <stop offset="0" stopColor={palette.cyan} />
          <stop offset=".5" stopColor={palette.blue} />
          <stop offset="1" stopColor={palette.violetBright} />
        </linearGradient>
        <radialGradient id={`${id}b`} cx=".36" cy=".32" r=".75">
          <stop offset="0" stopColor="#D6F3FF" />
          <stop offset=".42" stopColor="#3FA2FF" />
          <stop offset="1" stopColor={palette.blueDeep} />
        </radialGradient>
        <radialGradient id={`${id}h`}>
          <stop offset="0" stopColor="#5FB4FF" stopOpacity=".55" />
          <stop offset="1" stopColor="#5FB4FF" stopOpacity="0" />
        </radialGradient>
        {/* Far half of the orbit (behind the Q), near half (in front of it). */}
        <clipPath id={`${id}f`}><rect x="-300" y="-140" width="600" height="141.5" /></clipPath>
        <clipPath id={`${id}n`}><rect x="-300" y="0" width="600" height="140" /></clipPath>
        <clipPath id={`${id}nw`}><rect x="-300" y="-7" width="600" height="160" /></clipPath>
        <clipPath id={`${id}bh`}><path clipRule="evenodd" d={`M0 0H512V512H0Z${emblem.behindPath}`} /></clipPath>
        {/* Thin gaps where the tail and the near orbit pass over other shapes. */}
        <mask id={`${id}rc`} maskUnits="userSpaceOnUse" x="0" y="0" width="512" height="512">
          <rect width="512" height="512" fill="#fff" />
          <path d={emblem.tailPath} fill="#000" stroke="#000" strokeWidth="15" strokeLinejoin="miter" />
          {orbitCut}
        </mask>
        <mask id={`${id}tc`} maskUnits="userSpaceOnUse" x="0" y="0" width="512" height="512">
          <rect width="512" height="512" fill="#fff" />
          {orbitCut}
        </mask>
      </defs>
      <g clipPath={`url(#${id}bh)`}>
        <g transform={emblem.orbitTransform} clipPath={`url(#${id}f)`}>{orbit}</g>
      </g>
      <path d={emblem.ringPath} fillRule="evenodd" fill={`url(#${id}r)`} mask={`url(#${id}rc)`} />
      <path d={emblem.tailPath} fill={`url(#${id}t)`} mask={`url(#${id}tc)`} />
      <g transform={emblem.orbitTransform} clipPath={`url(#${id}n)`}>{orbit}</g>
      <circle cx={emblem.body.cx} cy={emblem.body.cy} r={emblem.body.halo} fill={`url(#${id}h)`} />
      <circle cx={emblem.body.cx} cy={emblem.body.cy} r={emblem.body.r} fill={`url(#${id}b)`} />
    </svg>
  );
}

/**
 * The QORVYNA wordmark. Letters use `currentColor`; the Q's tail and the A's
 * inner triangle carry the brand gradient. Size it by height (`h-4 w-auto`).
 */
export function QorvynaWordmark({ className, title }: { className?: string; title?: string }) {
  const id = useSvgId("qw");
  const label = title ? { role: "img" as const, "aria-label": title } : { "aria-hidden": true as const };
  return (
    <svg viewBox={`0 0 ${wordmark.width} ${wordmark.height}`} className={cn("brand-wordmark", className)} focusable="false" {...label}>
      <defs>
        <linearGradient id={`${id}a`} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stopColor={palette.cyan} />
          <stop offset="1" stopColor={palette.blue} />
        </linearGradient>
        <mask id={`${id}q`} maskUnits="userSpaceOnUse" x="-20" y="-20" width={wordmark.width + 40} height={wordmark.height + 40}>
          <rect x="-20" y="-20" width={wordmark.width + 40} height={wordmark.height + 40} fill="#fff" />
          <path d={wordmark.qTailGap} fill="#000" />
        </mask>
      </defs>
      <path d={wordmark.qBowl} fillRule="evenodd" fill="currentColor" mask={`url(#${id}q)`} />
      {wordmark.ink.map((d, index) => (
        <path key={index} d={d} fillRule="evenodd" fill="currentColor" />
      ))}
      {wordmark.accent.map((d, index) => (
        <path key={index} d={d} fill={`url(#${id}a)`} />
      ))}
    </svg>
  );
}

/** The tagline, set as a small tracked caption. Stacks on narrow screens. */
export function BrandTagline({ className }: { className?: string }) {
  return (
    <p className={cn("brand-tagline", className)}>
      {BRAND.taglineParts.map((part) => (
        <span key={part}>{part}</span>
      ))}
    </p>
  );
}

/** Horizontal lockup used in headers, sidebars and footers. */
export function Logo({
  size = "md",
  href = "/",
  showWordmark = true,
  className,
}: {
  size?: "sm" | "md" | "lg";
  href?: string;
  showWordmark?: boolean;
  className?: string;
}) {
  const mark = { sm: "h-7 w-7", md: "h-9 w-9", lg: "h-11 w-11" };
  const word = { sm: "h-[11px]", md: "h-[13px]", lg: "h-4" };
  return (
    <Link href={href} className={cn("brand-logo group inline-flex min-w-0 items-center gap-2 text-ink", className)} aria-label={`${BRAND.name} home`}>
      <QorvynaMark className={cn(mark[size], "shrink-0")} />
      {showWordmark ? <QorvynaWordmark className={cn(word[size], "brand-logo-word w-auto shrink-0")} /> : null}
    </Link>
  );
}

/** Vertical brand lockup used on the sign-in screens and other brand moments. */
export function BrandLockup({ className, size = "lg", tagline = true }: { className?: string; size?: "md" | "lg"; tagline?: boolean }) {
  const mark = size === "lg" ? "h-[4.5rem] w-[4.5rem] sm:h-20 sm:w-20" : "h-14 w-14";
  const word = size === "lg" ? "h-[22px] sm:h-[26px]" : "h-[18px]";
  return (
    <div className={cn("flex flex-col items-center gap-4 text-ink", className)}>
      <QorvynaMark className={mark} title={BRAND.name} />
      <div className="flex flex-col items-center gap-3">
        <QorvynaWordmark className={cn(word, "w-auto")} />
        {tagline ? <BrandTagline /> : null}
      </div>
    </div>
  );
}
